-- Eleven additional 2025 IPA FE Subject A public items, checked against questions and answer PDF.
-- Question 14 has a complex network diagram and is not included in this text-only batch.
-- Stable IDs; never remove or update existing user history.
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-03', 'exam-fe', 'データ構造・アルゴリズム', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問3】次の木構造は二分探索木であり，a～g の値は重複しない。値の大小関係として適切なものはどれか。

木構造：根は a，その左の子は b，右の子は c。b の左の子 d，右の子 e。c の左の子 f，右の子 g。', '[{"id":"a","text":"a ＜ b ＜ d ＜ e ＜ c ＜ f ＜ g"},{"id":"b","text":"d ＜ b ＜ e ＜ a ＜ f ＜ c ＜ g"},{"id":"c","text":"d ＜ e ＜ f ＜ g ＜ b ＜ c ＜ a"},{"id":"d","text":"g ＜ f ＜ c ＜ e ＜ d ＜ b ＜ a"}]', '"b"', '二分探索木の中順走査は左部分木・根・右部分木の順。結果は d,b,e,a,f,c,g。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-04', 'exam-fe', 'システム稼働率', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問4】MTBF 4,000 時間，MTTR 1,000 時間の装置がある。今後の 6 年間は，予防保守によって MTBF を毎年 100 時間ずつ改善し，遠隔保守によって MTTR を毎年 100 時間ずつ改善する。6 年後の稼働率は幾らか。', '[{"id":"a","text":"0.88"},{"id":"b","text":"0.90"},{"id":"c","text":"0.92"},{"id":"d","text":"0.94"}]', '"c"', 'MTBF 4600、MTTR 400。稼働率は 4600÷(4600＋400)=0.92。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-06', 'exam-fe', 'SQL・データベース', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問6】次の「商品」表に対する SQL と同じ結果を得る SELECT 文はどれか。

商品ID / 商品名称 / 仕入先ID / 単価
S001 / 冷蔵庫 / M001 / 155000
S002 / 食器洗い機 / M002 / 85000
S003 / 電子レンジ / M003 / 78000
S004 / 炊飯器 / M003 / 32000
S005 / コーヒーメーカー / M004 / 15000
S006 / ホットプレート / M004 / 12000

〔SQL 文〕
SELECT * FROM 商品 WHERE 仕入先ID IN (''M002'', ''M004'')', '[{"id":"a","text":"SELECT * FROM 商品 WHERE 仕入先ID = ''M002'' AND 仕入先ID = ''M004''"},{"id":"b","text":"SELECT * FROM 商品 WHERE 仕入先ID = ''M002'' INTERSECT SELECT * FROM 商品 WHERE 仕入先ID = ''M004''"},{"id":"c","text":"SELECT * FROM 商品 WHERE 仕入先ID = ''M002'' OR 仕入先ID = ''M004''"},{"id":"d","text":"SELECT * FROM 商品 WHERE 仕入先ID BETWEEN ''M002'' AND ''M004''"}]', '"c"', 'IN(''M002'',''M004'') は M002 または M004 の行だけを選ぶ。OR が等価。BETWEEN では M003 も含まれる。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-07', 'exam-fe', 'ネットワーク', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問7】1 G バイトの動画データを 40 M ビット／秒の回線でダウンロードしたところ 5 分掛かった。このとき回線利用率はおよそ何％か。ダウンロード時には動画データに 20％の制御情報が付加される。', '[{"id":"a","text":"10"},{"id":"b","text":"53"},{"id":"c","text":"67"},{"id":"d","text":"80"}]', '"d"', '1 GB = 8 Gbit，制御情報込みで 9.6 Gbit。理論上は 40 Mbit/s×300s=12 Gbit，9.6÷12=80%。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-09', 'exam-fe', '暗号・セキュリティ', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問9】暗号の危殆化に該当するものはどれか。', '[{"id":"a","text":"ある CA のデジタル証明書の有効期限が切れた。"},{"id":"b","text":"ある暗号アルゴリズムの秘密鍵が不正アクセスによって漏えいした。"},{"id":"c","text":"あるハッシュ関数において，ハッシュ値が同じになるデータの組を現実的な時間内に発見する方法が見つかった。"},{"id":"d","text":"あるランサムウェアで暗号化されたファイルの復号鍵が公開された。"}]', '"c"', '危殆化は暗号方式自体に対する実用的な攻撃が見つかり安全性が低下すること。鍵漏えいや証明書期限切れとは異なる。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-15', 'exam-fe', '情報セキュリティ監査', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問15】サーバ室の物理的な安全対策について，情報セキュリティ管理基準に照らして監査した結果，監査報告書の指摘事項とすべき状況はどれか。', '[{"id":"a","text":"サーバが設置されている施設の無人領域では，営業時間中でも警報装置が作動する。"},{"id":"b","text":"サーバ室に非常口，避難器具，誘導灯などを設置している。"},{"id":"c","text":"社外からサーバ室へ直接出入りするドアを設置しているが，出入りを考慮して常時施錠していない。"},{"id":"d","text":"場所が分からないように，サーバ室の所在を室外に表示していない。"}]', '"c"', '社外からアクセスできるサーバ室の入口は適切な施錠や入退室管理が必要。常時開放はセキュリティ上の指摘対象。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-16', 'exam-fe', 'データマイニング', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問16】データマイニングの手法の一つであって，POS などの蓄積データから「一緒に買われる商品」の組合せを発見する分析手法はどれか。', '[{"id":"a","text":"3C 分析"},{"id":"b","text":"ABC 分析"},{"id":"c","text":"コンジョイント分析"},{"id":"d","text":"マーケットバスケット分析"}]', '"d"', 'マーケットバスケット分析は同時購入商品の相関関係や併売パターンを発見する。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-17', 'exam-fe', '生成 AI・情報管理', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問17】インターネット上の生成 AI サービスを利用する際に，オプトアウトを設定することはどのような場合に有効か。', '[{"id":"a","text":"利用者が生成 AI から得た情報に対して著作権を主張したい場合"},{"id":"b","text":"利用者が入力した情報を生成 AI の学習に利用させたくない場合"},{"id":"c","text":"利用者が入力した情報を生成 AI を通じて他の利用者にも知ってほしい場合"},{"id":"d","text":"生成 AI から得た情報の信ぴょう性を高めたい場合"}]', '"b"', '学習利用のオプトアウトは，入力した情報をモデル学習に使わせない目的で設定する。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-18', 'exam-fe', 'マーケティング', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問18】物販事業において，ロングテールをビジネスとして成功させるために必要な施策はどれか。', '[{"id":"a","text":"多くの有名ブランド店が出店するショッピングモールの構築"},{"id":"b","text":"交通の利便性が高い地域に生活必需品を広く浅く取りそろえた出店計画"},{"id":"c","text":"店舗で購入した商品を近隣地域に無償配送するサービス"},{"id":"d","text":"豊富な品ぞろえと，在庫コストや配送費用を抑えるための大規模な物流センタの構築や活用"}]', '"d"', '販売数が少ない商品を幅広く揃えて利益を確保するには，品ぞろえと効率的な物流・在庫管理が重要。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-19', 'exam-fe', '損益分岐点分析', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問19】次の条件で喫茶店を開業したい。月 10 万円の利益を出すためには，1 客席当たり 1 日平均何人の客が必要か。

客 1 人当たり売上高：500 円
客 1 人当たり変動費：100 円
固定費：300,000 円／月
1 か月の営業日数：20 日
客席数：10 席', '[{"id":"a","text":"3.75"},{"id":"b","text":"4"},{"id":"c","text":"4.2"},{"id":"d","text":"5"}]', '"d"', '必要な限界利益は固定費30万円＋目標利益10万円=40万円。1人当たり限界利益400円なので月1000人。20日×10席で割ると1席1日5人。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-ipa-official-2025-a-20', 'exam-fe', '環境・サステナビリティ', 'standard', 'single_choice', '【2025年度 IPA公開問題 科目A 問20】カーボンフットプリントの説明として，適切なものはどれか。', '[{"id":"a","text":"温室効果ガスの排出量から吸収量と除去量を差し引いた合計をゼロにする取組"},{"id":"b","text":"原材料調達から廃棄・リサイクルに至るライフサイクル全体の温室効果ガス排出量を CO2 換算で商品やサービスに表示すること"},{"id":"c","text":"自動車エンジンから排出される大気汚染物質の排出量の定め"},{"id":"d","text":"商品が生産され，流通し，販売される場所を把握する仕組み"}]', '"b"', 'カーボンフットプリントは製品・サービスのライフサイクル全体の温室効果ガス排出量を CO₂ 換算して可視化する。', 'official', 'https://www.ipa.go.jp/shiken/mondai-kaiotu/sg_fe/koukai/tbl5kb0000005r9r-att/2025r07_fe_kamoku_a_qs.pdf', 'ja', 'A', 'explicit');
